"""HTTP client for the workstation SANA server (backend/image_server/sana_server.py)."""
import requests

from config import Config

REMOTE_TIMEOUT_SECONDS = 300


def generate_png(prompt, negative_prompt, height, width, steps, guidance, seed):
    """Return PNG bytes generated by the remote server. Raises on any failure."""
    if not Config.SANA_REMOTE_URL:
        raise RuntimeError("SANA_REMOTE_URL is not configured")
    resp = requests.post(
        f"{Config.SANA_REMOTE_URL.rstrip('/')}/generate_image",
        json={
            "prompt": prompt,
            "negative_prompt": negative_prompt,
            "height": height,
            "width": width,
            "steps": steps,
            "guidance": guidance,
            "seed": seed,
        },
        headers={"X-Token": Config.SANA_REMOTE_TOKEN},
        timeout=REMOTE_TIMEOUT_SECONDS,
    )
    if resp.status_code != 200:
        raise RuntimeError(f"remote SANA server returned {resp.status_code}: {resp.text[:200]}")
    if not resp.headers.get("Content-Type", "").startswith("image/png") or not resp.content:
        raise RuntimeError("remote SANA server did not return a PNG")
    return resp.content
